### C++ 

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int n;
	if (!(cin >> n)) return 0;
	long long S0 = 0; // 余数为0的元素总和
	const long long NEG = LLONG_MIN / 4; // 负无穷哨值，防溢出
	long long dp1 = NEG, dp2 = NEG; // 以余数1/2结尾的最大和

	for (int i = 0; i < n; ++i) {
		long long x; cin >> x;
		int r = (int)(x % 3);
		if (r == 0) {
			// 全为正数，余0可全部取
			S0 += x;
		} else if (r == 1) {
			long long cand = x; // 新开序列
			if (dp2 != NEG) cand = max(cand, dp2 + x); // 接在以2结尾后
			dp1 = max(dp1, cand);
			dp1 = max(dp1, x); // 再次确保至少可取自身
		} else { // r == 2
			long long cand = x; // 新开序列
			if (dp1 != NEG) cand = max(cand, dp1 + x); // 接在以1结尾后
			dp2 = max(dp2, cand);
			dp2 = max(dp2, x);
		}
	}

	long long ans = S0;
	ans = max(ans, dp1);
	ans = max(ans, dp2);
	cout << ans << "\n";
	return 0;
}
```

