import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    S0 = 0               # 余数为0的元素总和
    NEG = -10**30        # 负无穷哨兵值
    dp1 = NEG            # 以余数1结尾的最大和
    dp2 = NEG            # 以余数2结尾的最大和

    for _ in range(n):
        x = int(next(it))
        r = x % 3
        if r == 0:
            # 余0全取
            S0 += x
        elif r == 1:
            # 余1：新开，或接在余2后面
            cand = x
            if dp2 != NEG:
                cand = max(cand, dp2 + x)
            dp1 = max(dp1, cand, x)
        else:  # r == 2
            # 余2：新开，或接在余1后面
            cand = x
            if dp1 != NEG:
                cand = max(cand, dp1 + x)
            dp2 = max(dp2, cand, x)

    ans = max(S0, dp1, dp2)
    print(ans)

if __name__ == "__main__":
    main()
```

